#define DT_DRV_COMPAT zephyr_espi_emul

#include <zephyr/drivers/espi.h>
#include <zephyr/drivers/espi_emul.h>
#include <zephyr/logging/log.h>
#include <zephyr/kernel.h>

LOG_MODULE_REGISTER(espi_emul, CONFIG_ESPI_EMUL_LOG_LEVEL);

struct espi_emul_data {
	struct espi_callback callback;
	struct k_sem tx_sem;
	struct k_sem rx_sem;
	uint8_t tx_buf[CONFIG_ESPI_EMUL_TX_BUF_SIZE];
	uint8_t rx_buf[CONFIG_ESPI_EMUL_RX_BUF_SIZE];
	uint32_t tx_len;
	uint32_t rx_len;
	bool tx_ready;
	bool rx_ready;
};

struct espi_emul_config {
	const struct device *host_dev;
};

static int espi_emul_read_lpc_io(const struct device *dev, uint32_t reg, uint32_t *val)
{
	struct espi_emul_data *data = dev->data;
	const struct espi_emul_config *config = dev->config;

	return espi_read_lpc_io(config->host_dev, dev, reg, val, data->callback.signal);
}

static int espi_emul_write_lpc_io(const struct device *dev, uint32_t reg, uint32_t val)
{
	struct espi_emul_data *data = dev->data;
	const struct espi_emul_config *config = dev->config;

	return espi_write_lpc_io(config->host_dev, dev, reg, val, data->callback.signal);
}

